const listTwinProposalReviews = `-- name: ListTwinProposalReviews :many
SELECT id, workspace_id, proposal_id, decision, reviewer_id, reason, created_at FROM twin_proposal_review
WHERE workspace_id = $1
ORDER BY created_at DESC
`

func (q *Queries) ListTwinProposalReviews(ctx context.Context, workspaceID pgtype.UUID) ([]TwinProposalReview, error) {
	rows, err := q.db.Query(ctx, listTwinProposalReviews, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TwinProposalReview{}
	for rows.Next() {
		var i TwinProposalReview
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ProposalID,
			&i.Decision,
			&i.ReviewerID,
			&i.Reason,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

